// PROJETO 1 — GOOGLE (docs/PROJETO-1-GOOGLE-2026-09-17.md) — a página de intenção.
//
// Uma rota, 100 páginas (lib/seo/intentPages.ts): "AI video generator for X", "AI Y generator",
// "AI video generator in Z", "W alternative". O que a página tem que os concorrentes não têm:
// filmes REAIS da casa com o selo do motor real (vitrine do fundador), o que a pessoa escreve e o
// que sai, preço e trial lidos da fonte única (nunca literal) e um botão que abre o Studio com o
// prompt daquele nicho já na caixa. Honestidade: nada de "grátis" para motor que o trial não cobre;
// a família 'alternative' fala só da Kineo.
import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import Footer from '@/components/Footer'
import OrganicCtaLink from '@/components/OrganicCtaLink'
import { FREE_FILM_LABEL, getFreeTierOffer, swapFreeTierCopy as ft, trialFilmsForEngine, TRIAL_CREDITS_SHOWN, TRIAL_SEEDANCE15_FILMS } from '@/lib/freeTierOffer'
import { STARTER_MONTH, STARTER_CREDITS, creditsPerReferenceVideo } from '@/lib/marketingPrice'
import { PUBLIC_ENGINE_EXAMPLES } from '@/lib/publicExamples'
import { getIntentPage, INTENT_FAMILY_LABEL, INTENT_HUB_PATH, INTENT_PAGES, INTENT_SLUGS, intentPagePath, type IntentEngine } from '@/lib/seo/intentPages'
import { PaginaClaraCards, PaginaClaraTopo, PaginaClaraVitrine } from '@/components/seo/PaginaClara' // KINEO-PAGINAS-IA-CLARAS-2110 — o menu do topo, os 4 cards e a vitrine atual da home
import { PAGINA_CLARA_CLASSE, PAGINA_CLARA_FUNDO } from '@/lib/seo/paginasIaClaras2110' // KINEO-PAGINAS-IA-CLARAS-2110

const OFFER = getFreeTierOffer()
const BASE = 'https://www.usekineo.com'
const ENGINE_NAME: Record<IntentEngine, string> = { fast: 'Kineo 1', cinematic_ai: 'Seedance 1.5' }

export const dynamic = 'force-static'
export const dynamicParams = false

export function generateStaticParams() {
  return INTENT_SLUGS.map((slug) => ({ slug }))
}

export function generateMetadata({ params }: { params: { slug: string } }): Metadata {
  const p = getIntentPage(params.slug)
  if (!p) return {}
  const url = `${BASE}${intentPagePath(p.slug)}`
  const description = `${p.intro.slice(0, 150).replace(/\s+\S*$/, '')}… Real films, ${ENGINE_NAME[p.engine]} and generative engines, free trial with no card.`
  return {
    metadataBase: new URL(BASE),
    title: p.title,
    description,
    alternates: { canonical: url },
    openGraph: { title: p.title, description, url, type: 'website' },
    twitter: { card: 'summary_large_image', title: p.title, description },
  }
}

/** Studio já com o prompt do nicho na caixa; cadastro preserva o destino (mesmo padrão das páginas por motor). */
function studioHref(slug: string, prompt: string, engine: IntentEngine, language?: string): string {
  const campaign = `intent_${slug}`.slice(0, 100)
  // Revisão da E2b (texto, achado 1): SEM duração cravada. Com duration=60 o "Make this film free" abria um Seedance de
  // 60 s (25 cr) para o trial de 10 — não era grátis. Sem ?duration, o Studio escolhe a maior duração que o saldo paga
  // (lib/growth/entradaSeedance15 duracaoDeEntrada): o trial abre no filme grátis de 15 s.
  // e o motor viaja no vocabulário do Studio (cinematic_ai não é chave de lá e era ignorado em silêncio).
  const studio = new URLSearchParams({ engine: engine === 'cinematic_ai' ? 'seedance' : engine, prompt, script_mode: 'ai', intent_campaign: campaign })
  if (language) studio.set('language', language) // KINEO-IDIOMAS-15: a página de idioma abre o Studio já na língua
  // KINEO-ORIGEM-HONESTA-2026-09-23 — SEM utm_source/utm_medium cravados. O link
  // dizia `utm_source=google` para todo mundo, e quem chegava do ChatGPT (ou de
  // qualquer outro lugar) e se cadastrava por aqui virava 'google' em
  // profiles.signup_utm_source. Conferido em lib/analytics.ts (captureSourceOnce):
  // first-touch grava utm_* quando existem e, sem utm, grava `referrer` =
  // sanitizeAcquisitionReferrer(document.referrer) — o referrer EXTERNO do
  // pouso (chatgpt.com, google.com); um pouso sem utm e sem referrer não grava
  // nada, para que um pouso externo posterior ainda vença. E em
  // lib/acquisitionSource.ts (acquisitionSource): utm explícito vence; sem utm,
  // a origem sai do host do referrer (sourceFromHost). Portanto, sem utm_source
  // aqui, a origem registrada é a REAL. utm_campaign e intent_campaign ficam:
  // são a página, não a origem.
  const signup = new URLSearchParams({ utm_campaign: campaign, intent_campaign: campaign, redirect: `/studio?${studio.toString()}` })
  return `/signup?${signup.toString()}`
}

const CARD = { background: '#FFFFFF', border: '1px solid #E4E4E0', borderRadius: 16 } as const

export default function IntentPage({ params }: { params: { slug: string } }) {
  const p = getIntentPage(params.slug)
  if (!p) notFound()
  const url = `${BASE}${intentPagePath(p.slug)}`
