            {pasteNote ? <>Prefer to paste? The <a href="/chatgpt" style={{ color: C.accent, textDecoration: 'none', fontWeight: 700 }}>paste page</a>{' '}
            still works. </> : null}The Kineo MCP app for the ChatGPT store is in review.
          </p>
        </StepCard>
      </ol>
  )
}

