// KINEO-PAGINAS-IA-CLARAS-2110 — cores em var(--kpl-*, <cor de antes>): claras só dentro de <main className="kpl"> (as páginas de entrada do ChatGPT); nas outras páginas, a cor de antes.
import { useState } from 'react'
import { rememberSignupCampaign, trackEvent } from '@/lib/analytics'
import {
  buildAuthenticatedCreationRedirect,
  CREATION_HANDOFF_PROMPT_MAX_CHARS,
  type CreationIntent,
} from '@/lib/creationHandoff'
import {
  formatLimitCounter,
  formatPromptLimitTrimAction,
  formatPromptLimitTrimNotice,
  promptLimitPreservedMessage,
  promptLimitState,
  trimPromptToLimit,
  type PromptLimitLocale,
} from '@/lib/studioPromptLimit'
import type { NarrationLanguage } from '@/lib/textLanguage'

const TOPIC_EXAMPLES = [
  'The island too dangerous to visit',
  'Why the Door to Hell is still burning',
  'How compound interest grows $100',
] as const

type TopicGeneratorFormProps = {
  campaign?: string
  source?: string
  placement?: string
  utmSource?: string
  utmMedium?: string
  examples?: readonly string[]
  formId?: string
  // KINEO-PORTAS-16-LINGUAS-2026-09-20: qualquer código do catálogo (o Studio lê ?language= com narrationLanguage()).
  language?: NarrationLanguage
  scriptMode?: 'ai' | 'verbatim'
  duration?: 35 | 45 | 60 | 90
  creationIntent?: Exclude<CreationIntent, null>
  preserveHandoffForSignedIn?: boolean
  analyticsVariant?: string
  marginTop?: number
  copy?: {
    label: string
    placeholder: string
    submit: string
    examplesLabel: string
    note: string
  }
}

export default function TopicGeneratorForm({
  campaign = 'push70_youtube_topic_one_click',
  source = 'push70_youtube_topic_one_click',
  placement = 'hero_form',
  // Keep these opt-in. A blanket seo/organic default would overwrite the real
  // first touch when ChatGPT, a directory or another referral brought the
  // visitor to a public page. The campaign carries the page handoff while
  // acquisition UTMs remain truthful.
  utmSource,
  utmMedium,
  examples = TOPIC_EXAMPLES,
  formId = 'try-a-topic',
  language,
  scriptMode,
  duration,
  creationIntent = 'fast',
  preserveHandoffForSignedIn = false,
  analyticsVariant,
  marginTop = 30,
  copy = {
    label: 'What should your Short be about?',
    placeholder: 'Type one topic or paste your script',
    submit: 'Turn this topic into a Short →',
    examplesLabel: 'Example topics',
    note: 'Your topic stays attached through signup. Free to start: 10 credits, no card.',
  },
}: TopicGeneratorFormProps = {}) {
  const [topic, setTopic] = useState('')
  const [trimNotice, setTrimNotice] = useState<string | null>(null)
  const inputId = `${formId}-input`
  // O contador de caracteres só tem copy em en/pt/es; as outras 13 línguas caem no inglês (só número + 'characters').
  const limitLocale: PromptLimitLocale = language === 'pt' || language === 'es' ? language : 'en'
  const limit = promptLimitState(topic, CREATION_HANDOFF_PROMPT_MAX_CHARS)
  const canSubmit = limit.length >= 3 && !limit.over

  function trimToFit() {
    const result = trimPromptToLimit(topic, CREATION_HANDOFF_PROMPT_MAX_CHARS)
    setTopic(result.text)
    setTrimNotice(formatPromptLimitTrimNotice(result.removed, limitLocale))
  }

  function authRedirectFor(promptValue: string): string | null {
    if (!preserveHandoffForSignedIn) return null
    return buildAuthenticatedCreationRedirect({
      prompt: promptValue,
      campaign,
      createIntent: creationIntent,
      language,
      scriptMode,
      duration,
    })
  }

  function startWithExample(example: string, exampleIndex: number) {
    rememberSignupCampaign(campaign)
    const metadata = {
      source,
      placement: 'topic_example_one_click',
      example_index: exampleIndex,
      topic_length: example.length,
      ...(language ? { language } : {}),
      ...(scriptMode ? { script_mode: scriptMode } : {}),
      ...(duration ? { duration_seconds: duration } : {}),
      creation_intent: creationIntent,
      ...(analyticsVariant ? { variant: analyticsVariant } : {}),
    }
    void trackEvent('organic_topic_example_started', metadata)
    void trackEvent('organic_topic_submitted', metadata)
    // KINEO-STARTER-EM-ARTIGO-2026-08-15 — este componente é a máquina de
    // ativação de 68% (push69/push70) e, até hoje, era INVISÍVEL para a única
    // métrica pela qual a casa julga página orgânica. O gate de 14/08 comparou
    // 13 páginas por `organic_cta_clicked` e leu `/cheapest-ai-shorts-maker`
    // como "0 cliques em 41 sessões" — mas aquela página TEM este starter
    // desde #78, e ele emitia `organic_topic_example_started` /
    // `organic_topic_submitted`, nunca `organic_cta_clicked`. O zero media o
    // instrumento, não a porta. Agora um clique no starter aparece na MESMA
    // consulta que a home, com `destination` no formato de OrganicCtaLink
    // (components/OrganicCtaLink.tsx:33-38) para que os dois sejam somáveis.
    // `keepalive: true` em trackEvent (lib/analytics.ts:428) é o que faz este
    // evento sobreviver ao window.location.assign logo abaixo.
    //
    // `mirrors` NÃO é enfeite: um clique escreve DUAS linhas para preservar a
    // consulta histórica por `organic_cta_clicked`. O painel do fundador
    // ignora o espelho e deduplica por pessoa; uma ação continua uma intenção.
    void trackEvent('organic_cta_clicked', {
      ...metadata,
      destination: '/signup',
      mirrors: 'organic_topic_submitted',
    })
    const params = new URLSearchParams({
      prompt: example,
      create_intent: creationIntent,
      intent_campaign: campaign,
    })
    if (utmSource) params.set('utm_source', utmSource)
    if (utmMedium) params.set('utm_medium', utmMedium)
    if (utmSource || utmMedium) params.set('utm_campaign', campaign)
    if (language) params.set('language', language)
    if (scriptMode) params.set('script_mode', scriptMode)
    if (duration) params.set('duration', String(duration))
    const authRedirect = authRedirectFor(example)
    if (authRedirect) params.set('redirect', authRedirect)
    window.location.assign(`/signup?${params.toString()}`)
  }

  return (
    <div
      id={formId}
      style={{
        marginTop,
        scrollMarginTop: 24,
        border: '1px solid var(--kpl-accent-line, rgba(41,151,255,0.35))',
        borderRadius: 18,
        background: 'linear-gradient(145deg, var(--kpl-accent-soft, rgba(41,151,255,0.10)), var(--kpl-zebra, rgba(255,255,255,0.025)))',
        padding: 18,
      }}
    >
      <form
        action="/signup"
        method="get"
        onSubmit={(event) => {
          if (!canSubmit) {
            event.preventDefault()
            return
          }
          rememberSignupCampaign(campaign)
          const submitMetadata = {
            source,
            placement,
            topic_length: topic.trim().length,
            ...(language ? { language } : {}),
            ...(scriptMode ? { script_mode: scriptMode } : {}),
            ...(duration ? { duration_seconds: duration } : {}),
            creation_intent: creationIntent,
            ...(analyticsVariant ? { variant: analyticsVariant } : {}),
          }
          void trackEvent('organic_topic_submitted', submitMetadata)
          // Mesma razão do starter acima: digitar o próprio tema e apertar o
          // botão é a saída para o produto, e precisa aparecer na consulta que
          // decide se uma página orgânica vive ou morre. `mirrors` preserva a
          // série histórica; o painel deduplica a intenção por pessoa.
          void trackEvent('organic_cta_clicked', {
            ...submitMetadata,
            destination: '/signup',
            mirrors: 'organic_topic_submitted',
          })
        }}
      >
        <label htmlFor={inputId} style={{ display: 'block', fontSize: 13, fontWeight: 800, color: 'var(--kpl-text, #f5f5f7)', marginBottom: 9 }}>
          {copy.label}
        </label>
        <textarea
          id={inputId}
          name="prompt"
          value={topic}
          onChange={(event) => {
            setTopic(event.target.value)
            setTrimNotice(null)
          }}
          required
          minLength={3}
          rows={3}
          placeholder={copy.placeholder}
          style={{
            display: 'block',
            width: '100%',
            resize: 'vertical',
            minHeight: 96,
            border: '1px solid var(--kpl-line, #3a3a3d)',
            borderRadius: 13,
            background: 'var(--kpl-card, #0b0b0d)',
            color: 'var(--kpl-text, #f5f5f7)',
            padding: '14px 15px',
            font: 'inherit',
            fontSize: 16,
            lineHeight: 1.45,
            outline: 'none',
          }}
        />
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 10, marginTop: 8 }}>
          <span
            aria-live="polite"
            style={{ color: limit.over ? 'var(--kpl-err, #ff8a80)' : 'var(--kpl-muted, #86868b)', fontSize: 12, fontWeight: 700 }}
          >
            {formatLimitCounter(limit, limitLocale)}
          </span>
          {limit.over ? (
            <button
              type="button"
              onClick={trimToFit}
              style={{ border: '1px solid var(--kpl-line2, #5c5c60)', borderRadius: 999, background: 'var(--kpl-card, #161618)', color: 'var(--kpl-text, #f5f5f7)', padding: '6px 10px', fontSize: 12, fontWeight: 800, cursor: 'pointer' }}
            >
              {formatPromptLimitTrimAction(limit.excess, limitLocale)}
            </button>
          ) : null}
        </div>
        {limit.over ? (
          <p role="alert" style={{ color: 'var(--kpl-err, #ffb4ab)', fontSize: 12, lineHeight: 1.45, margin: '7px 0 0' }}>
            {promptLimitPreservedMessage(limitLocale)}
          </p>
        ) : trimNotice ? (
          <p role="status" style={{ color: 'var(--kpl-ok, #a7f3d0)', fontSize: 12, lineHeight: 1.45, margin: '7px 0 0' }}>
            {trimNotice}
          </p>
        ) : null}
        <input type="hidden" name="create_intent" value={creationIntent} />
        <input type="hidden" name="intent_campaign" value={campaign} />
        {authRedirectFor(topic) && (
          <input type="hidden" name="redirect" value={authRedirectFor(topic) ?? ''} />
        )}
        {utmSource && <input type="hidden" name="utm_source" value={utmSource} />}
        {utmMedium && <input type="hidden" name="utm_medium" value={utmMedium} />}
        {(utmSource || utmMedium) && <input type="hidden" name="utm_campaign" value={campaign} />}
        {language && <input type="hidden" name="language" value={language} />}
        {scriptMode && <input type="hidden" name="script_mode" value={scriptMode} />}
        {duration && <input type="hidden" name="duration" value={duration} />}
        <button
          type="submit"
          disabled={!canSubmit}
          style={{
            display: 'block',
            width: '100%',
            marginTop: 12,
            border: 0,
            borderRadius: 999,
            background: 'var(--kpl-accent, #f5f5f7)',
            color: 'var(--kpl-on-accent, #000)',
            padding: '14px 22px',
            fontSize: 15,
            fontWeight: 900,
            cursor: canSubmit ? 'pointer' : 'not-allowed',
            opacity: canSubmit ? 1 : 0.55,
          }}
        >
          {copy.submit}
        </button>
      </form>

      {examples.length > 0 && (
        <div aria-label={copy.examplesLabel} style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 13 }}>
          {examples.map((example, exampleIndex) => (
            <button
              key={example}
              type="button"
              onClick={() => startWithExample(example, exampleIndex)}
              style={{
                border: '1px solid var(--kpl-line, #343438)',
                borderRadius: 999,
                background: 'var(--kpl-card, #161618)',
                color: 'var(--kpl-muted, #a1a1a6)',
                padding: '7px 10px',
                fontSize: 12,
                cursor: 'pointer',
              }}
            >
              {example} →
            </button>
          ))}
        </div>
      )}

      <p style={{ margin: '13px 0 0', color: 'var(--kpl-muted, #86868b)', fontSize: 12, lineHeight: 1.5 }}>
        {copy.note}
      </p>
    </div>
  )
