}
function dadosDa(world) {
  const ed = edicaoImportada(world.over)
  return JSON.parse(world.over[`${DATA_DIR}/${ed}.json`] ?? rd(`${DATA_DIR}/${ed}.json`))
}
/** O motor-manchete: o primeiro do índice (ordem da lib) com bloco de cliente. */
