function numerosNoCodigo(src, kind) {
  const sf = ts.createSourceFile('x.' + kind, src, ts.ScriptTarget.Latest, true, kind === 'tsx' ? ts.ScriptKind.TSX : ts.ScriptKind.TS)
  const out = []
