    gerarStillDaEstrela: async (a) => { edits.push(a); n++; return respostas.editFalha ? { url: null, motivo: 'provider_failed' } : { url: `https://f/edit-${n}.jpg`, motivo: 'ok' } },
    fetch: async (_u, init) => {
