const deliveryHead = git('log', '--format=%H', `--grep=^${MARCA} `, '-1', 'HEAD').trim() // KINEO-ROTEIRO-CURTO-SEM-FALHA-2026-10-22 — limit historical ownership to the marked delivery; current runtime/mutants remain unchanged.
