    const clipSec = two.clipSecondsForTarget(key, 5)
    const clipCr = clipPricing.clipCreditCost(key, clipSec, false)
    const f35 = cost.creditCostForDuration(quality, true, 35)
    const f60 = cost.creditCostForDuration(quality, true, 60)
    const smallest = tiers.find(([t]) => pricing.TIER_CREDITS[t] >= f60) ?? null
    // KINEO-S25-ABRE-2026-10-06 — reancorado: o Seedance 2.5 voltou (S25_PUBLIC) como motor SÓ DE PLANO PAGO e sem clipe avulso
    // para o público, com rota própria. As mesmas provas valem para ele, na versão honesta: primeira frase "onde usar + quanto
    // custa" sem preço de clipe e com "on any paid plan", tabela sem linha de clipe, nota de acesso "on paid plans" no lugar do
    // trial, CTA "… on a paid plan →" para o cadastro com a campanha, e a página servida é a rota própria (não a do [engine]).
    const soPago = launch.engineIsPaidPlansOnly(key)
    // REANCORADO KINEO-S25-CLIPES-2026-10-06: o clipe do 2.5 está à venda conforme o interruptor ÚNICO dele (lib/clips/clipLaunch.ts
    // CLIP_S25_PUBLIC → clipS25Visible), não mais o s25ClipVisible de lib/engineLaunch.ts (que saiu). Mesmas provas nos dois estados.
    const clipeAVenda = key !== 's25' || clipLaunch.clipS25Visible(null)
    const rotulo = soPago ? `Make a ${e.name} video on a paid plan →` : `Make a ${e.name} video →`
    // KINEO-S25-CLIPES-2026-10-06 — motor pago COM clipe à venda: "<motor> clips from N credits (paid plans)", N = o clipe mais
    // barato do catálogo (clipCreditCost em cada duração oferecida). Motor aberto ou sem clipe à venda: a frase nunca aparece.
    const fraseDe = soPago && clipeAVenda ? `${e.name} clips from ${Math.min(...clipCat.offeredSecondsFor(key).map((s) => clipPricing.clipCreditCost(key, s, false)))} credits (paid plans)` : null
    esperado[slug] = { name: e.name, clipSec, clipCr, f35, f60, soPago, clipeAVenda, fraseDe }
    const html = ROTA_PROPRIA[slug]
      ? renderToStaticMarkup(await load(ROTA_PROPRIA[slug]).default())
      : renderToStaticMarkup(await load(PAGE).default({ params: { engine: slug } }))
    const t = texto(html)
    // primeira frase depois do H1
    const depoisH1 = html.slice(html.indexOf('</h1>'))
    const primeiroP = depoisH1.match(/<p\b[^>]*>[\s\S]*?<\/p>/)?.[0] ?? ''
    if (!primeiroP.startsWith('<p data-kineo="engine-answer"')) p.push(`${slug}: o primeiro parágrafo depois do H1 não é a resposta citável`)
    const lead = texto(primeiroP)
    const frase1 = `You can use ${e.name} online in Kineo Studio`
    if (!lead.startsWith(frase1)) p.push(`${slug}: a resposta não começa por "${frase1}"`)
    if (clipeAVenda) {
      if (!lead.includes(`a ${clipSec}-second ${e.name} clip costs ${clipCr} credits (about ${usd(usdOf(clipCr))})`)) p.push(`${slug}: preço do clipe na 1ª frase ≠ fonte (${clipCr} cr, ${usd(usdOf(clipCr))})`)
      if (!lead.includes(`video with voice, captions and music costs ${f60} credits (about ${usd(usdOf(f60))})`)) p.push(`${slug}: preço do filme de 60 s na 1ª frase ≠ fonte (${f60} cr)`)
    } else {
      // KINEO-S25-ABRE-2026-10-06 — sem clipe à venda: a 1ª frase dá o filme de 35 e de 60 s, nunca preço de clipe
      if (/-second [^.]* clip costs/.test(lead)) p.push(`${slug}: 1ª frase anuncia clipe que não se vende`)
      if (!lead.includes(`costs ${f35} credits for 35 seconds (about ${usd(usdOf(f35))}) or ${f60} credits for 60 seconds (about ${usd(usdOf(f60))})`)) p.push(`${slug}: preço do filme de 60 s na 1ª frase ≠ fonte (${f35}/${f60} cr)`)
    }
    if (soPago && !lead.includes(', on any paid plan:')) p.push(`${slug}: 1ª frase não diz que o motor é só de plano pago`)
    if (!soPago && lead.includes('on any paid plan')) p.push(`${slug}: 1ª frase diz "plano pago" de motor aberto ao trial`)
    if (smallest && !lead.includes(`is ${smallest[1]} at ${money(pricing.TIER_PRICES[smallest[0]].usd)}/month`)) p.push(`${slug}: menor plano ≠ fonte (${smallest[1]})`)
    // tabela
    const card = html.match(/<section data-kineo="engine-price-card"[\s\S]*?<\/section>/)?.[0] ?? ''
    if (!card) p.push(`${slug}: sem a tabela de preço`)
    const linhas = [...card.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/g)].map((m) => [...m[1].matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/g)].map((c) => texto(c[1])))
    const exp = [...(clipeAVenda ? [[`${clipSec}-second clip`, clipCr]] : []), ['35-second video', f35], ['60-second video', f60]] // KINEO-S25-ABRE-2026-10-06
    if (!clipeAVenda && linhas.some((l) => /-second clip/.test(l[0] ?? ''))) p.push(`${slug}: tabela com linha de clipe que não se vende`)
    for (const [rotulo, cr] of exp) {
      const linha = linhas.find((l) => l[0]?.startsWith(rotulo))
      const planos = tiers.map(([t]) => { const n = Math.floor(pricing.TIER_CREDITS[t] / cr); return n > 0 ? `${n} per month` : '—' })
      if (!linha || linha[1] !== `${cr} cr` || linha[2] !== usd(usdOf(cr)) || JSON.stringify(linha.slice(3)) !== JSON.stringify(planos)) {
        p.push(`${slug}: linha "${rotulo}" ≠ fonte (${JSON.stringify(linha)} vs ${cr} cr ${usd(usdOf(cr))} ${planos})`)
      }
    }
    for (const [tier, label] of tiers) {
      if (!card.includes(`${label} (${money(pricing.TIER_PRICES[tier].usd)}/mo · ${pricing.TIER_CREDITS[tier]} cr)`)) p.push(`${slug}: cabeçalho do plano ${label} ≠ checkout`)
    }
    // comparação direta (só fonte oficial, datada)
    const geo = cat.ENGINE_GEO[slug]
    if (!geo) { p.push(`${slug}: indexável sem camada citável`); continue }
    // REANCORADO KINEO-S25-CLIPES-2026-10-06 (correção de fato público): o 2.5 compara com a Runway PRO — runway.com/pricing (06/10)
    // lista o Seedance 2.5 só no Pro e no Max. Os outros motores seguem com as cotações de sempre.
    const cotacoes = { kling: 'runway-k25-standard', hollywood: 'runway-k3-standard', h3: 'runway-h3-standard', s25: 'runway-s25-pro' }
    for (const r of geo.direct) {
      for (const s of r.sources) {
        let host = ''
        try { host = new URL(s.url).hostname } catch { /* inválida */ }
        if (!OFICIAIS.includes(host) || !s.url.startsWith('https://')) p.push(`${slug}: fonte não oficial ${s.url}`)
        if (!card.includes(`href="${s.url}"`)) p.push(`${slug}: link da fonte ausente ${s.url}`)
      }
      if (geoLib.monthYear(r.checkedOn) !== 'October 2026') p.push(`${slug}: preço direto sem data de outubro/2026 (${r.checkedOn})`)
      if (r.clipUsdCents === null) continue
      let esperadoCents = null
      if (r.who.startsWith('Runway')) {
        const q = market.MARKET_QUOTES.find((x) => x.id === cotacoes[key])
        esperadoCents = q && q.source === 'oficial' ? Math.round((q.creditsPerSecond * clipSec * q.plan.usdCentsMonthly) / q.plan.creditsMonthly) : null
      } else if (r.who.startsWith('Google')) {
        esperadoCents = Math.round(geoLib.FONTES_DIRETAS.geminiVeoFast.usdPerSecondFrom * clipSec * 100)
      }
      if (esperadoCents === null || r.clipUsdCents !== esperadoCents) p.push(`${slug}: ${r.who} ≈ ${r.clipUsdCents} ≠ cotação oficial ${esperadoCents}`)
      if (!texto(card).includes(`About ${usd(r.clipUsdCents)} for ${clipSec} seconds of raw video.`)) p.push(`${slug}: preço direto de ${r.who} fora do HTML`)
    }
    if (!geo.direct.length && !geo.directNote) p.push(`${slug}: sem comparação direta e sem aviso honesto`)
    // KINEO-S25-CLIPES-2026-10-06 — comparação pública só com plano que a página oficial do concorrente LISTA com o modelo
    // (lib/clips/clipPriceVsMarket.ts MODEL_PLAN_LISTINGS; o Seedance 2.5 na Runway: só Pro e Max, runway.com/pricing 06/10).
    const listagens = market.MODEL_PLAN_LISTINGS[market.ENGINE_MARKET[key].model] ?? []
    for (const r of geo.direct) {
      const quem = /^(\S+) \((\w+) plan\)$/.exec(r.who)
      const listagem = quem ? listagens.find((l) => l.competitor === quem[1]) : null
      if (listagem && !listagem.plans.includes(quem[2])) p.push(`${slug}: cita ${r.who}, plano que a página oficial não lista com o modelo`)
    }
    if (key === 'seedance' && !(geo.directNote && card.includes('href="https://www.byteplus.com/en/product/modelark"'))) p.push('seedance: aviso honesto da BytePlus ausente')
    // CTA → campanha + motor; frase da marca de apoio
    const cta = card.match(/<a href="([^"]+)"[^>]*>(Make a [^<]+ →)<\/a>/) // KINEO-S25-ABRE-2026-10-06: "… video →" ou "… video on a paid plan →"
    const hrefEsperado = intent.buildEngineLandingSignupHref({ engine: key, campaign: `seo_engine_${slug}` })
    if (!cta || unesc(cta[1]) !== hrefEsperado || cta[2] !== rotulo) p.push(`${slug}: CTA do card ≠ cadastro com a campanha (${cta && unesc(cta[1])})`) // KINEO-S25-ABRE-2026-10-06: rótulo do motor (pago: "… on a paid plan →")
    else {
      const u = new URL(unesc(cta[1]), BASE)
      const redirect = new URL(u.searchParams.get('redirect') ?? '', BASE)
      if (u.pathname !== '/signup' || u.searchParams.get('intent_campaign') !== `seo_engine_${slug}` || redirect.pathname !== '/studio' || redirect.searchParams.get('engine') !== key || redirect.searchParams.get('intent_campaign') !== `seo_engine_${slug}`) {
        p.push(`${slug}: CTA não leva o motor e seo_engine_${slug} até o Studio`)
      }
    }
    const depoisCta = texto(card.slice(card.indexOf(cta?.[0] ?? '§')))
    if (!depoisCta.includes(BRAND) || !depoisCta.includes(REWARDS)) p.push(`${slug}: frase da marca não está logo abaixo do CTA`)
    if (/qualif/i.test(texto(card))) p.push(`${slug}: promete que o vídeo "se qualifica"`)
    // os CTAs de cadastro da página (hero, quando não é o par Seedance/Veo, e final) levam o mesmo destino
    const ctasPagina = [...html.matchAll(/<a href="([^"]+)"[^>]*>(Make a [^<]+ →)<\/a>/g)] // KINEO-S25-ABRE-2026-10-06: inclui "… on a paid plan →"
    if (ctasPagina.length < 2 || ctasPagina.some((m) => unesc(m[1]) !== hrefEsperado || m[2] !== rotulo)) p.push(`${slug}: CTAs "Make a … video" da página fora do destino com campanha`)
    // mentiras corrigidas
    if (t.includes('3–7 minutes')) p.push(`${slug}: ainda promete 3–7 minutes`)
    // REANCORADO KINEO-GEO-RODADA3-2026-10-08 — o tempo honesto agora é o medido (ver a régua acima); a faixa digitada não volta.
    const tempoMedido = medido(quality)
    if (/(^|[^0-9])8\s*–\s*25 minutes/.test(t) || !tempoMedido || !t.includes(`Median ${tempoMedido.m} min from request to finished film`)) p.push(`${slug}: tempo de entrega honesto ausente`)
    if (/unlocked on every account/.test(t)) p.push(`${slug}: ainda diz "unlocked on every account"`)
    // KINEO-S25-ABRE-2026-10-06 — motor só de plano pago: a nota diz isso e NUNCA oferece o trial como porta.
    if (soPago) {
      if (!t.includes(`${e.name} is on paid plans — the free trial does not include it.`)) p.push(`${slug}: nota de acesso sem "on paid plans"`)
      if (/New accounts[^.]* start with \d+ free credits/.test(t)) p.push(`${slug}: motor pago oferece o trial na nota de acesso`)
    } else if (!t.includes(`New accounts${trial.GRANT_COUNTRY_CLAUSE} start with ${trial.TRIAL_CREDITS_SHOWN} free credits`)) p.push(`${slug}: nota de acesso sem a cláusula do país`)
    if (fraseDe ? !t.includes(`${fraseDe}.`) : / clips from \d+ credits \(paid plans\)/.test(t)) p.push(`${slug}: frase "clips from … (paid plans)" ${fraseDe ? 'ausente' : 'onde não cabe'}`) // KINEO-S25-CLIPES-2026-10-06
    // FAQ citável no JSON-LD (o que a IA lê)
    const ld = [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map((m) => { try { return JSON.parse(m[1]) } catch { return null } })
    const faq = ld.find((x) => x && x['@type'] === 'FAQPage')
    const q = faq?.mainEntity?.find((x) => x.name === `Where can I use ${e.name} online, and what does a ${e.name} video cost?`)
    const faqClipe = clipeAVenda ? q?.acceptedAnswer.text.includes(`a ${clipSec}-second ${e.name} clip costs ${clipCr} credits`) : !/clip costs/.test(q?.acceptedAnswer.text ?? '') // KINEO-S25-ABRE-2026-10-06
    const faqPago = !soPago || (q?.acceptedAnswer.text ?? '').includes('on any paid plan (the free trial does not include it)')
    if (!q || !faqClipe || !faqPago || !q.acceptedAnswer.text.includes(`${f35} credits for 35 seconds or ${f60} credits for 60 seconds`)) p.push(`${slug}: FAQ citável ausente ou ≠ fonte no JSON-LD`)
    // tier derivado
    const tierEsperado = smallest ? smallest[1] : 'Studio'
    if (e.tier !== tierEsperado) p.push(`${slug}: tier "${e.tier}" ≠ menor plano que paga 60 s (${tierEsperado})`)
  }

  // (7b) as 26 páginas traduzidas (Seedance 1.5 e Veo 3.1 × 13 línguas): tempo honesto e trial com a cláusula do país
  const EL = load('lib/seo/enginePageLangs.ts')
  const restrito = trial.GRANT_COUNTRY_CLAUSE !== ''
  if (EL.TRIAL_ONLY_IN_SUPPORTED_COUNTRIES !== restrito) p.push(`enginePageLangs: espelho do país (${EL.TRIAL_ONLY_IN_SUPPORTED_COUNTRIES}) ≠ GRANT_COUNTRY_CLAUSE (${restrito})`)
  const fx = { engine: 'Veo 3.1', credits: cost.creditCostForDuration('cinematic_veo', true, 60), trial: trial.TRIAL_CREDITS_SHOWN }
  for (const code of EL.ENGINE_LANG_CODES) {
    const Lg = EL.ENGINE_LANGS[code]
    const veoMedido = medido('cinematic_veo') // REANCORADO KINEO-GEO-RODADA3-2026-10-08 — a página passa a mediana medida do motor
    const faqs = Lg.faq({ ...fx, covers: false, starter: 'X', ...(veoMedido ? { medianMinutes: veoMedido.mediana, indicative: veoMedido.indicativo } : {}) })
    const trialTextos = [Lg.description(fx), Lg.cost({ ...fx, covers: false, starter: 'X' }), faqs[1].a]
    const clausula = CLAUSULA_PAIS[code]
    if (!clausula) p.push(`${code}: língua sem cláusula de país conhecida pelo guardião`)
    else if (restrito && !trialTextos.every((s) => s.includes(clausula))) p.push(`${code}: trial prometido sem a cláusula do país`)
    else if (!restrito && trialTextos.some((s) => s.includes(clausula))) p.push(`${code}: cláusula do país com a política "todos"`)
    const tempo = faqs[2].a
    // REANCORADO KINEO-GEO-RODADA3-2026-10-08 (com motivo): a faixa "8–25" saiu das 13 línguas; no lugar, a mediana MEDIDA do
    // motor (ponto ou vírgula, conforme a língua). Segue vermelho se voltar o "3–7" (M22) ou uma faixa digitada.
    if (/(^|[^0-9])3\s*(–|à|إلى|سے|से)\s*7([^0-9]|$)/.test(tempo)) p.push(`${code}: tempo de entrega ainda é 3–7 min`)
    else if (/(^|[^0-9])8\s*(–|à|إلى|سے|से)\s*25([^0-9]|$)/.test(tempo) || !veoMedido || !(tempo.includes(veoMedido.m) || tempo.includes(veoMedido.m.replace('.', ',')))) p.push(`${code}: tempo de entrega sem a mediana medida (ou com a faixa digitada)`)
  }

  // (3) motor fora: sem camada citável, página sem bloco novo e sem "unlocked on every account"
  for (const slug of fora) {
    if (cat.ENGINE_GEO[slug]) p.push(`${slug}: motor pausado com camada citável`)
    const html = renderToStaticMarkup(await load(PAGE).default({ params: { engine: slug } }))
    if (html.includes('data-kineo="engine-answer"') || html.includes('data-kineo="engine-price-card"')) p.push(`${slug}: página de motor pausado com resposta citável`)
    if (/unlocked on every account/.test(texto(html))) p.push(`${slug}: página pausada diz "unlocked on every account"`)
  }
  const layout = load(LAYOUT)
  for (const slug of cat.ENGINE_SLUGS) {
    const meta = layout.generateMetadata({ params: { engine: slug } })
    const noindex = meta?.robots?.index === false
    if (noindex !== fora.includes(slug)) p.push(`${slug}: layout ${noindex ? 'noindex' : 'indexável'} ≠ régua (fora=${fora.includes(slug)})`)
  }
  // títulos sem "free"
  for (const slug of cat.ENGINE_SLUGS) {
    const title = load(PAGE).generateMetadata({ params: { engine: slug } }).title ?? ''
    if (/\bfree\b/i.test(title)) p.push(`${slug}: título com "free"`)
  }

  // (5) sitemap
// KINEO-BING-SEO-1510 — reancorado com desfaz byte a byte: a rodada do Bing (15/10) carimba o lastmod das páginas que ela
// mudou (lib/seo/bingSeo1510Paths.ts), entre elas /ai-video-generator/seedance. As datas desta rodada continuam EXATAS no sitemap SEM a rodada do
// Bing (scripts/test-support/desfaz-bing-seo-1510.mjs: bloco ausente ou repetido lança); o carimbo novo é provado por
// scripts/test-bing-seo-1510.mjs.
  const sm = offlineModules({ replacements: { ...rep, [SITEMAP]: semBingSeo1510(SITEMAP, rep[SITEMAP] ?? rd(SITEMAP)) }, mocks: SITEMAP_MOCKS })(SITEMAP).default()
  const urls = sm.map((x) => x.url)
  // REANCORADO KINEO-GEO-RODADA2-2026-10-08 (com motivo): a rodada 2 de GEO (sessão CEO 08/10) mudou de verdade a página do
  // Seedance 1.5 ("é grátis?", 1.5 × 2.5, filmes reais) — o lastmod dela passa a ser a data REAL dessa revisão
  // (GEO_RODADA2_REVIEWED_ISO, lib/seo/houseFilmIdeas.ts), posterior a esta. As outras páginas de motor seguem exigindo a data
  // desta revisão; a prova da rodada 2 é scripts/test-geo-rodada2-2026-10-08.mjs.
  const rodada2 = new Date(`${load('lib/seo/houseFilmIdeas.ts').GEO_RODADA2_REVIEWED_ISO}T12:00:00.000Z`).getTime()
  if (!(rodada2 > lastmodGeo)) p.push('rodada 2: data da revisão não é posterior a esta')
  // REANCORADO KINEO-GEO-RODADA3-2026-10-08 (com motivo): a rodada 3 de GEO (sessão CEO 08/10) trocou de verdade o tempo de
  // entrega de TODA página de motor indexável e das traduzidas (faixa digitada → tempo medido do Kineo AI Video Index) e revisou
  // /seedance-vs-veo-vs-kling (resposta direta + tabela medida). Essas páginas passam a ter o lastmod real da rodada 3
  // (GEO_RODADA3_LAST_MODIFIED_ISO, lib/seo/geoRodada3.ts); a do Seedance 1.5 segue com o da rodada 2 (mesmo dia). O hub,
  // /models-pricing e /kineo-vs-higgsfield não mudaram e seguem exigindo a data desta revisão. Prova: test-geo-rodada3-2026-10-08.
  const rodada3 = new Date(load('lib/seo/geoRodada3.ts').GEO_RODADA3_LAST_MODIFIED_ISO).getTime()
  if (!(rodada3 > lastmodGeo)) p.push('rodada 3: data da revisão não é posterior a esta')
  const lastmodEsperado = (slug) => (slug === 'seedance' ? rodada2 : rodada3)
  for (const slug of indexaveis) {
    const ent = sm.filter((x) => x.url === `${BASE}/ai-video-generator/${slug}`)
    if (ent.length !== 1) p.push(`sitemap: ${slug} aparece ${ent.length}×`)
    else if (new Date(ent[0].lastModified).getTime() !== lastmodEsperado(slug)) p.push(`sitemap: ${slug} sem o lastmod real da revisão`)
  }
  for (const slug of fora) if (urls.some((u) => u === `${BASE}/ai-video-generator/${slug}` || u.startsWith(`${BASE}/ai-video-generator/${slug}/`))) p.push(`sitemap: motor pausado ${slug} no mapa`)
  const langs = load('lib/seo/enginePageLangs.ts')
  for (const slug of langs.LOCALIZED_ENGINE_SLUGS) for (const code of langs.ENGINE_LANG_CODES) {
    const u = `${BASE}/ai-video-generator/${slug}/${code}`
    const ent = sm.find((x) => x.url === u)
    if (indexaveis.includes(slug) && (!ent || new Date(ent.lastModified).getTime() !== rodada3)) p.push(`sitemap: ${u} ausente ou sem o lastmod da revisão`) // REANCORADO KINEO-GEO-RODADA3-2026-10-08
  }
  for (const path of ['/ai-video-generator', '/models-pricing', '/kineo-vs-higgsfield', '/seedance-vs-veo-vs-kling']) {
    const ent = sm.find((x) => x.url === `${BASE}${path}`)
    const quando = path === '/seedance-vs-veo-vs-kling' ? rodada3 : lastmodGeo // REANCORADO KINEO-GEO-RODADA3-2026-10-08 (a comparação foi revisada)
    if (!ent || new Date(ent.lastModified).getTime() !== quando) p.push(`sitemap: ${path} sem o lastmod da revisão`)
  }
  const cluster = sm.find((x) => x.url === `${BASE}/pricing`)
  if (!cluster || new Date(cluster.lastModified).getTime() === lastmodGeo) p.push('sitemap: re-datou página que esta revisão não tocou (/pricing)')

  // (5) llms.txt
  const L = createOfflineLoader({ env: { NODE_ENV: 'production', KINEO_REVERSE_TRIAL_ENABLED: 'true' }, globals: { Response, Date }, source: (rel, raw) => (Object.hasOwn(rep, rel) ? rep[rel] : raw) })
  const llms = await L(LLMS).GET().text()
  const ini = llms.indexOf('## Where to use each video engine online')
  const secao = ini >= 0 ? llms.slice(ini, llms.indexOf('\n## ', ini + 5)) : ''
  if (!secao) p.push('llms.txt: sem a seção "Where to use each video engine online"')
  for (const slug of comGeo) { // KINEO-H3MAX-2026-10-13 — só motores com camada citável
    const x = esperado[slug]
    const linha = secao.split('\n').find((l) => l.startsWith(`- [Where to use ${x.name} online](${BASE}/ai-video-generator/${slug})`)) ?? ''
    if (!(x.clipeAVenda ? linha.includes(`${x.clipSec}-second clip: ${x.clipCr} credits`) : !/-second clip:/.test(linha)) || (x.soPago && !linha.includes('paid plans only (not in the free trial)')) || !linha.includes(`60-second narrated video: ${x.f60} credits`) || !linha.includes(`35-second narrated video: ${x.f35} credits`)) p.push(`llms.txt: linha do ${x.name} ausente ou ≠ fonte`)
