  if (EL.TRIAL_ONLY_IN_SUPPORTED_COUNTRIES !== restrito) p.push(`enginePageLangs: espelho do país (${EL.TRIAL_ONLY_IN_SUPPORTED_COUNTRIES}) ≠ GRANT_COUNTRY_CLAUSE (${restrito})`)
  const fx = { engine: 'Veo 3.1', credits: cost.creditCostForDuration('cinematic_veo', true, 60), trial: trial.TRIAL_CREDITS_SHOWN }
  for (const code of EL.ENGINE_LANG_CODES) {
    const Lg = EL.ENGINE_LANGS[code]
    const veoMedido = medido('cinematic_veo') // REANCORADO KINEO-GEO-RODADA3-2026-10-08 — a página passa a mediana medida do motor
    const faqs = Lg.faq({ ...fx, covers: false, starter: 'X', ...(veoMedido ? { medianMinutes: veoMedido.mediana, indicative: veoMedido.indicativo } : {}) })
    const trialTextos = [Lg.description(fx), Lg.cost({ ...fx, covers: false, starter: 'X' }), faqs[1].a]
    const clausula = CLAUSULA_PAIS[code]
    if (!clausula) p.push(`${code}: língua sem cláusula de país conhecida pelo guardião`)
    else if (restrito && !trialTextos.every((s) => s.includes(clausula))) p.push(`${code}: trial prometido sem a cláusula do país`)
    else if (!restrito && trialTextos.some((s) => s.includes(clausula))) p.push(`${code}: cláusula do país com a política "todos"`)
    const tempo = faqs[2].a
    // REANCORADO KINEO-GEO-RODADA3-2026-10-08 (com motivo): a faixa "8–25" saiu das 13 línguas; no lugar, a mediana MEDIDA do
    // motor (ponto ou vírgula, conforme a língua). Segue vermelho se voltar o "3–7" (M22) ou uma faixa digitada.
    if (/(^|[^0-9])3\s*(–|à|إلى|سے|से)\s*7([^0-9]|$)/.test(tempo)) p.push(`${code}: tempo de entrega ainda é 3–7 min`)
    else if (/(^|[^0-9])8\s*(–|à|إلى|سے|से)\s*25([^0-9]|$)/.test(tempo) || !veoMedido || !(tempo.includes(veoMedido.m) || tempo.includes(veoMedido.m.replace('.', ',')))) p.push(`${code}: tempo de entrega sem a mediana medida (ou com a faixa digitada)`)
  }

  // (3) motor fora: sem camada citável, página sem bloco novo e sem "unlocked on every account"
  for (const slug of fora) {
    if (cat.ENGINE_GEO[slug]) p.push(`${slug}: motor pausado com camada citável`)
    const html = renderToStaticMarkup(await load(PAGE).default({ params: { engine: slug } }))
    if (html.includes('data-kineo="engine-answer"') || html.includes('data-kineo="engine-price-card"')) p.push(`${slug}: página de motor pausado com resposta citável`)
    if (/unlocked on every account/.test(texto(html))) p.push(`${slug}: página pausada diz "unlocked on every account"`)
  }
  const layout = load(LAYOUT)
  for (const slug of cat.ENGINE_SLUGS) {
    const meta = layout.generateMetadata({ params: { engine: slug } })
    const noindex = meta?.robots?.index === false
    if (noindex !== fora.includes(slug)) p.push(`${slug}: layout ${noindex ? 'noindex' : 'indexável'} ≠ régua (fora=${fora.includes(slug)})`)
  }
  // títulos sem "free"
  for (const slug of cat.ENGINE_SLUGS) {
    const title = load(PAGE).generateMetadata({ params: { engine: slug } }).title ?? ''
    if (/\bfree\b/i.test(title)) p.push(`${slug}: título com "free"`)
  }

  // (5) sitemap
// KINEO-BING-SEO-1510 — reancorado com desfaz byte a byte: a rodada do Bing (15/10) carimba o lastmod das páginas que ela
// mudou (lib/seo/bingSeo1510Paths.ts), entre elas /ai-video-generator/seedance. As datas desta rodada continuam EXATAS no sitemap SEM a rodada do
// Bing (scripts/test-support/desfaz-bing-seo-1510.mjs: bloco ausente ou repetido lança); o carimbo novo é provado por
// scripts/test-bing-seo-1510.mjs.
  const sm = offlineModules({ replacements: { ...rep, [SITEMAP]: semBingSeo1510(SITEMAP, rep[SITEMAP] ?? rd(SITEMAP)) }, mocks: SITEMAP_MOCKS })(SITEMAP).default()
  const urls = sm.map((x) => x.url)
  // REANCORADO KINEO-GEO-RODADA2-2026-10-08 (com motivo): a rodada 2 de GEO (sessão CEO 08/10) mudou de verdade a página do
  // Seedance 1.5 ("é grátis?", 1.5 × 2.5, filmes reais) — o lastmod dela passa a ser a data REAL dessa revisão
  // (GEO_RODADA2_REVIEWED_ISO, lib/seo/houseFilmIdeas.ts), posterior a esta. As outras páginas de motor seguem exigindo a data
  // desta revisão; a prova da rodada 2 é scripts/test-geo-rodada2-2026-10-08.mjs.
  const rodada2 = new Date(`${load('lib/seo/houseFilmIdeas.ts').GEO_RODADA2_REVIEWED_ISO}T12:00:00.000Z`).getTime()
  if (!(rodada2 > lastmodGeo)) p.push('rodada 2: data da revisão não é posterior a esta')
  // REANCORADO KINEO-GEO-RODADA3-2026-10-08 (com motivo): a rodada 3 de GEO (sessão CEO 08/10) trocou de verdade o tempo de
  // entrega de TODA página de motor indexável e das traduzidas (faixa digitada → tempo medido do Kineo AI Video Index) e revisou
  // /seedance-vs-veo-vs-kling (resposta direta + tabela medida). Essas páginas passam a ter o lastmod real da rodada 3
  // (GEO_RODADA3_LAST_MODIFIED_ISO, lib/seo/geoRodada3.ts); a do Seedance 1.5 segue com o da rodada 2 (mesmo dia). O hub,
  // /models-pricing e /kineo-vs-higgsfield não mudaram e seguem exigindo a data desta revisão. Prova: test-geo-rodada3-2026-10-08.
  const rodada3 = new Date(load('lib/seo/geoRodada3.ts').GEO_RODADA3_LAST_MODIFIED_ISO).getTime()
  if (!(rodada3 > lastmodGeo)) p.push('rodada 3: data da revisão não é posterior a esta')
  const lastmodEsperado = (slug) => (slug === 'seedance' ? rodada2 : rodada3)
  for (const slug of indexaveis) {
    const ent = sm.filter((x) => x.url === `${BASE}/ai-video-generator/${slug}`)
    if (ent.length !== 1) p.push(`sitemap: ${slug} aparece ${ent.length}×`)
    else if (new Date(ent[0].lastModified).getTime() !== lastmodEsperado(slug)) p.push(`sitemap: ${slug} sem o lastmod real da revisão`)
  }
  for (const slug of fora) if (urls.some((u) => u === `${BASE}/ai-video-generator/${slug}` || u.startsWith(`${BASE}/ai-video-generator/${slug}/`))) p.push(`sitemap: motor pausado ${slug} no mapa`)
  const langs = load('lib/seo/enginePageLangs.ts')
  for (const slug of langs.LOCALIZED_ENGINE_SLUGS) for (const code of langs.ENGINE_LANG_CODES) {
    const u = `${BASE}/ai-video-generator/${slug}/${code}`
    const ent = sm.find((x) => x.url === u)
    if (indexaveis.includes(slug) && (!ent || new Date(ent.lastModified).getTime() !== rodada3)) p.push(`sitemap: ${u} ausente ou sem o lastmod da revisão`) // REANCORADO KINEO-GEO-RODADA3-2026-10-08
  }
  for (const path of ['/ai-video-generator', '/models-pricing', '/kineo-vs-higgsfield', '/seedance-vs-veo-vs-kling']) {
    const ent = sm.find((x) => x.url === `${BASE}${path}`)
    const quando = path === '/seedance-vs-veo-vs-kling' ? rodada3 : lastmodGeo // REANCORADO KINEO-GEO-RODADA3-2026-10-08 (a comparação foi revisada)
    if (!ent || new Date(ent.lastModified).getTime() !== quando) p.push(`sitemap: ${path} sem o lastmod da revisão`)
  }
  const cluster = sm.find((x) => x.url === `${BASE}/pricing`)
  if (!cluster || new Date(cluster.lastModified).getTime() === lastmodGeo) p.push('sitemap: re-datou página que esta revisão não tocou (/pricing)')

  // (5) llms.txt
  const L = createOfflineLoader({ env: { NODE_ENV: 'production', KINEO_REVERSE_TRIAL_ENABLED: 'true' }, globals: { Response, Date }, source: (rel, raw) => (Object.hasOwn(rep, rel) ? rep[rel] : raw) })
  const llms = await L(LLMS).GET().text()
  const ini = llms.indexOf('## Where to use each video engine online')
  const secao = ini >= 0 ? llms.slice(ini, llms.indexOf('\n## ', ini + 5)) : ''
  if (!secao) p.push('llms.txt: sem a seção "Where to use each video engine online"')
  for (const slug of comGeo) { // KINEO-H3MAX-2026-10-13 — só motores com camada citável
    const x = esperado[slug]
    const linha = secao.split('\n').find((l) => l.startsWith(`- [Where to use ${x.name} online](${BASE}/ai-video-generator/${slug})`)) ?? ''
    if (!(x.clipeAVenda ? linha.includes(`${x.clipSec}-second clip: ${x.clipCr} credits`) : !/-second clip:/.test(linha)) || (x.soPago && !linha.includes('paid plans only (not in the free trial)')) || !linha.includes(`60-second narrated video: ${x.f60} credits`) || !linha.includes(`35-second narrated video: ${x.f35} credits`)) p.push(`llms.txt: linha do ${x.name} ausente ou ≠ fonte`)
    // KINEO-S25-CLIPES-2026-10-06 — o preço direto do llms.txt é o MESMO da página (mesmo concorrente, mesmo plano, mesmo valor)
    for (const r of (cat.ENGINE_GEO[slug]?.direct ?? []).filter((route) => route.clipUsdCents !== null)) {
      if (!linha.includes(`${r.who}, about ${usd(r.clipUsdCents)} for ${r.seconds} seconds`)) p.push(`llms.txt: ${x.name} sem o preço direto de ${r.who}`)
    }
  }
  for (const slug of fora) if (secao.includes(`/ai-video-generator/${slug})`)) p.push(`llms.txt: motor pausado ${slug} na seção de onde usar`)
  // KINEO-H3MAX-2026-10-13 — o H3 Max não aparece na seção de onde usar (sem clipe à venda) e a novidade datada cita os preços da régua.
  if (launch.H3MAX_PUBLIC && (secao.includes('/ai-video-generator/minimax-h3-max)') || !llms.includes(`- 2026-10-13: MiniMax H3 Max is live on Kineo`) || !llms.includes(`costs ${cost.creditCostForDuration('cinematic_h3max', true, 35)} credits for 35 seconds or ${cost.creditCostForDuration('cinematic_h3max', true, 60)} for 60 seconds`))) p.push('llms.txt: H3 Max fora da regra (seção de onde usar ou novidade datada)')
  // KINEO-S25-CLIPES-2026-10-06 — a novidade do motor pago com clipe à venda cita "<motor> clips from N credits (paid plans)";
  // sem clipe à venda, a frase não aparece em lugar nenhum do llms.txt.
  for (const slug of comGeo) { // KINEO-H3MAX-2026-10-13 — só motores com camada citável
    const x = esperado[slug]
    if (x.fraseDe && !llms.includes(`${x.fraseDe}.`)) p.push(`llms.txt: ${x.name} sem "${x.fraseDe}"`)
  }
  if (!comGeo.some((slug) => esperado[slug].fraseDe) && / clips from \d+ credits \(paid plans\)/.test(llms)) p.push('llms.txt: "clips from … (paid plans)" sem clipe pago à venda')
  const arena = llms.split('\n').find((l) => l.startsWith('- [Engine Arena]')) ?? ''
  if (/\bseven\b/i.test(arena)) p.push('llms.txt: Engine Arena ainda fala em "seven"')
  const facts = L('lib/kineoFacts.ts')
  const veoFact = facts.ENGINE_FACTS.find((f) => f.name === 'Veo 3.1')
  if (!veoFact || /native audio/i.test(veoFact.what)) p.push('kineoFacts: Veo ainda diz "native audio" (a casa desliga o áudio do modelo)')

  // (4) robots
  const R = createOfflineLoader({ source: (rel, raw) => (Object.hasOwn(rep, rel) ? rep[rel] : raw) })(ROBOTS).default()
  for (const bot of AI_BOTS) {
    const grupo = R.rules.find((g) => (Array.isArray(g.userAgent) ? g.userAgent : [g.userAgent]).includes(bot))
    if (!grupo) { p.push(`robots: ${bot} sem grupo explícito`); continue }
    const allow = [].concat(grupo.allow ?? []), disallow = [].concat(grupo.disallow ?? [])
    if (!allow.includes('/')) p.push(`robots: ${bot} sem Allow: /`)
    if (disallow.some((d) => d === '/' || '/ai-video-generator/seedance'.startsWith(d))) p.push(`robots: ${bot} bloqueado nas páginas de motor`)
  }
  return p
}

