        }
      })
    }
    if (typeof IntersectionObserver === 'undefined') { set(true); return }
    const io = new IntersectionObserver((entries) => entries.forEach((entry) => set(entry.isIntersecting)), { threshold: 0.3 })
    io.observe(root)
    return () => io.disconnect()
  }, [ref])
}

