// ─── (1) a lib dos cards ─────────────────────────────────────────────────────
function libProblems(src) {
  const probs = []
  if (/^\s*import\s/m.test(src) || /\brequire\(/.test(src)) probs.push('lib com import (tem de ser pura)')
  let M
  try { M = roda(src, 'lib dos cards') } catch (e) { return [`lib não roda: ${e.message}`] }
